INSERT INTO email_templates (id, name, category, description, subject, html, text, created_at) VALUES
('tpl-abandoned-friendly', 'Abandoned Cart (Friendly)', 'abandoned_cart', 'A gentle reminder email to encourage customers to complete their purchase.', 'Still thinking it over?', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>Still thinking it over?</h2><p>Your items are waiting for you. Complete your purchase before they''re gone.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#4f46e5;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Complete Your Order</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'Still thinking it over? Your items are waiting for you. Complete your order: {{CTA_LINK}}', CURRENT_TIMESTAMP),
('tpl-abandoned-discount', 'Abandoned Cart (Discount)', 'abandoned_cart', 'Complete your purchase and enjoy 10% off your order.', 'Don''t miss out!', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>Don''t miss out!</h2><p>Complete your purchase and enjoy 10% off your order.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#f97316;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Shop Now &amp; Save</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'Complete your purchase and enjoy 10% off: {{CTA_LINK}}', CURRENT_TIMESTAMP),
('tpl-abandoned-urgency', 'Abandoned Cart (Urgency)', 'abandoned_cart', 'Finish your order before your items sell out.', 'Your cart misses you', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>Your cart misses you</h2><p>Finish your order before your items sell out.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#16a34a;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Return to Cart</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'Finish your order before your items sell out: {{CTA_LINK}}', CURRENT_TIMESTAMP),
('tpl-welcome', 'Welcome', 'welcome', 'Welcome new subscribers and introduce your store.', 'Welcome to {{STORE_NAME}}!', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>Welcome!</h2><p>Thanks for joining us. Here''s 10% off your first order.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#4f46e5;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Start Shopping</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'Welcome! Thanks for joining us: {{CTA_LINK}}', CURRENT_TIMESTAMP),
('tpl-promo', 'Promotion', 'promotions', 'Announce a sale or promotional offer.', 'Big discounts on all products', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>Sale is here!</h2><p>Enjoy big discounts across the store for a limited time.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#e11d48;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Shop the Sale</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'Sale is here! Shop now: {{CTA_LINK}}', CURRENT_TIMESTAMP),
('tpl-reengagement', 'Re-engagement', 're_engagement', 'Win back inactive customers.', 'We miss you', '<div style="font-family:sans-serif;max-width:480px;margin:0 auto;padding:32px;text-align:center;"><h2>We miss you</h2><p>It''s been a while - come back and enjoy 10% off.</p><p><a href="{{CTA_LINK}}" style="display:inline-block;background:#0891b2;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;">Come Back &amp; Save</a></p><p style="margin-top:32px;font-size:12px;color:#888;"><a href="{{UNSUBSCRIBE_LINK}}">Unsubscribe</a></p></div>', 'We miss you - come back and save: {{CTA_LINK}}', CURRENT_TIMESTAMP);
